-- Стартап: фінансова модель (калькулятор окупності). Тексти опор (ідея/маркетинг/технічна/фінанси) — у canvas_json.
ALTER TABLE startups ADD COLUMN finance_json TEXT NOT NULL DEFAULT '{}';

INSERT INTO changelog (title, body, created_at) VALUES
('Стартапи: чотири опори — Ідея, Маркетинг, Технічна, Фінанси',
'Робочий простір стартапу тепер побудований навколо чотирьох опор. Ідея — біль, для кого, рішення, цінність, конкуренти, ризики. Маркетинг — позиціонування, оффер, ідеальний клієнт, канали, повідомлення, докази, запуск перших 10 клієнтів, воронка, назва. Технічна — обсяг MVP, ядро, стек, дані, інтеграції, сервер, система оновлень, безпека, обслуговування; з неї Джері збирає повний промпт (ТЗ) для Claude Code — кнопка там же, копіюєш і кидаєш у Claude. Фінанси — модель грошей, тарифи, витрати і живий калькулятор: ціна, витрати, реклама, нові клієнти, ріст, відтік → прибуток за рік, місяць окупності, скільки клієнтів для нуля і для бажаного доходу, графік на 2 роки. На «Огляді» видно готовність кожної опори. «Експорт проєкту» — усе одним файлом (.md або PDF). Джері заповнює все це сам (startup_update: canvas і finance).',
'2026-10-31 22:00:00');
